function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function beltAllowed(itemBelt, sel) {
  if (sel === "All" || itemBelt === "All") return true;
  return BELT_ORDER.indexOf(itemBelt) <= BELT_ORDER.indexOf(sel);
}

// Resolve a technique to its image key: prefer "<Belt>_<Name>" (new files),
// fall back to the original plain "<Name>" key (the first 36 illustrated techniques).
function imgKeyFor(t) {
  const k = t.belt + "_" + t.name;
  if (IMAGES[k]) return k;
  if (IMAGES[t.name]) return t.name;
  return null;
}
function name2key(name) {
  const t = TECHNIQUES.find(x => x.name === name);
  if (t) return imgKeyFor(t);
  return IMAGES[name] ? name : null;
}

function imgTechniques(belt) {
  return TECHNIQUES.filter(t => imgKeyFor(t) && beltAllowed(t.belt, belt));
}

function buildIdentify(belt, reverse) {
  const pool = imgTechniques(belt);
  return shuffle(pool).map(t => {
    const meta = CATS[t.category];
    let sameCat = TECHNIQUES.filter(x => x.category === t.category && x.name !== t.name && imgKeyFor(x) && beltAllowed(x.belt, belt));
    if (sameCat.length < 3) sameCat = TECHNIQUES.filter(x => x.category === t.category && x.name !== t.name && imgKeyFor(x));
    const distract = shuffle(sameCat).slice(0, 3).map(x => x.name);
    return {
      type: reverse ? "reverse" : "identify",
      answer: t.name,
      image: IMAGES[imgKeyFor(t)],
      options: shuffle([t.name, ...distract]),
      accent: meta.accent, badge: meta.badge, label: t.category,
    };
  });
}

function buildClassify(belt) {
  const pool = TECHNIQUES.filter(t => t.subType && beltAllowed(t.belt, belt));
  return shuffle(pool).map(t => {
    const meta = CATS[t.category];
    const others = shuffle(SUBTYPES.filter(s => s !== t.subType)).slice(0, 3);
    const img = imgKeyFor(t) ? IMAGES[imgKeyFor(t)] : null;
    return {
      type: "classify",
      answer: t.subType,
      image: img,
      caption: img ? t.name : null,
      prompt: img ? null : t.name,
      options: shuffle([t.subType, ...others]),
      accent: meta.accent, badge: meta.badge, label: t.category,
    };
  });
}

function buildTerms(belt) {
  const pool = TERMS.filter(t => beltAllowed(t.belt, belt));
  return shuffle(pool).map(t => {
    const j2e = Math.random() < 0.5;
    const prompt = j2e ? t.jp : t.en;
    const answer = j2e ? t.en : t.jp;
    const others = TERMS.filter(x => x.jp !== t.jp);
    const distract = shuffle(others).slice(0, 3).map(x => (j2e ? x.en : x.jp));
    return {
      type: "terms",
      prompt, answer,
      options: shuffle([answer, ...distract]),
      accent: TERM_ACCENT, badge: TERM_BADGE,
      label: j2e ? "Japanese → English" : "English → Japanese",
    };
  });
}

function buildCards(mode, belt) {
  if (mode === "terms") return buildTerms(belt);
  if (mode === "classify") return buildClassify(belt);
  if (mode === "reverse") return buildIdentify(belt, true);
  if (mode === "sim") {
    return shuffle([...buildIdentify(belt, false), ...buildClassify(belt), ...buildTerms(belt)]);
  }
  return buildIdentify(belt, false); // identify
}

const MODES = [
  { id:"identify", icon:"🖼️", title:"Name the Technique", desc:"See the image, pick the name (illustrated techniques)" },
  { id:"reverse",  icon:"🔁", title:"Find the Image",     desc:"See the name, pick the image (illustrated techniques)" },
  { id:"classify", icon:"🗂️", title:"Classify the Waza",  desc:"Ashi · Koshi · Te · Sutemi · Shime · Kansetsu — full syllabus" },
  { id:"terms",    icon:"📖", title:"Terminology",         desc:"Japanese ↔ English — full glossary, all grades" },
  { id:"sim",      icon:"🎯", title:"Grading Simulation",  desc:"Mixed exam at the selected belt level" },
];

export default function JudoQuiz() {
  const [mode, setMode] = useState(null);
  const [belt, setBelt] = useState("Orange");
  const [cards, setCards] = useState([]);
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState(null);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);

  function start(m, b) {
    setMode(m); setBelt(b);
    setCards(buildCards(m, b));
    setIndex(0); setSelected(null); setScore(0); setDone(false);
  }
  function restart() { start(mode, belt); }
  function home() { setMode(null); setCards([]); }

  function handleSelect(opt) {
    if (selected !== null) return;
    setSelected(opt);
    if (opt === cards[index].answer) setScore(s => s + 1);
  }
  function handleNext() {
    if (index + 1 >= cards.length) setDone(true);
    else { setIndex(i => i + 1); setSelected(null); }
  }

  const wrap = { minHeight:"100vh", background:"linear-gradient(160deg,#120e04,#1e1608 60%,#120e04)", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"flex-start", fontFamily:"'Georgia',serif", padding:"20px 16px 40px", boxSizing:"border-box" };

  if (mode === null) return <StartScreen belt={belt} setBelt={setBelt} onStart={start} wrap={wrap} />;
  if (!cards.length) return <div style={wrap}><div style={{color:"#c09050",marginTop:60,marginBottom:18}}>No cards for this selection — try a different belt or mode.</div><GhostBtn onClick={home}>← Modes</GhostBtn></div>;

  const card = cards[index];
  const modeInfo = MODES.find(m => m.id === mode);
  const progress = Math.round(((index + (selected ? 1 : 0)) / cards.length) * 100);
  const question = card.type === "classify" ? "Which Waza family?" : card.type === "reverse" ? "Pick the matching image" : card.type === "terms" ? "Choose the correct translation" : "What is this technique?";
  const showImage = card.type === "identify" || (card.type === "classify" && card.image);
  const showText = card.type === "reverse" || card.type === "terms" || (card.type === "classify" && !card.image);

  return (
    <div style={wrap}>
      <div style={{ textAlign:"center", marginBottom:"18px", paddingTop:"8px" }}>
        <div style={{ fontSize:"10px", letterSpacing:"4px", color:"#806840", textTransform:"uppercase", marginBottom:"4px" }}>Grading-Syllabus-Revised-v2503011</div>
        <h1 style={{ margin:0, fontSize:"clamp(18px,4.5vw,28px)", fontWeight:"700", color:"#f0d070", letterSpacing:"1px", textShadow:"0 0 24px rgba(240,200,80,0.3)" }}>🥋 Judo Technique Quiz</h1>
        <div style={{ fontSize:"11px", color:"#705030", marginTop:"4px", letterSpacing:"2px" }}>{modeInfo.title.toUpperCase()} · {belt.toUpperCase()}</div>
      </div>

      {done ? <DoneScreen score={score} total={cards.length} onRestart={restart} onHome={home} /> : (
        <>
          <div style={{ width:"100%", maxWidth:"580px", marginBottom:"16px" }}>
            <div style={{ display:"flex", justifyContent:"space-between", fontSize:"11px", color:"#907050", marginBottom:"5px", letterSpacing:"1px" }}>
              <span>Card {index+1} / {cards.length}</span>
              <span>Score: {score} / {index+(selected?1:0)}</span>
            </div>
            <div style={{ height:"3px", background:"#2a1e08", borderRadius:"2px" }}>
              <div style={{ height:"100%", borderRadius:"2px", background:"linear-gradient(90deg,#f0c800,#f07820)", width:`${progress}%`, transition:"width 0.4s ease" }} />
            </div>
          </div>

          <div style={{ width:"100%", maxWidth:"580px", borderRadius:"14px", border:"1px solid rgba(240,200,80,0.18)", background:"linear-gradient(170deg,rgba(40,28,8,0.97),rgba(22,16,4,0.99))", boxShadow:"0 10px 50px rgba(0,0,0,0.7),inset 0 1px 0 rgba(240,200,80,0.08)", overflow:"hidden" }}>
            <div style={{ padding:"9px 18px", background:`linear-gradient(90deg,${card.accent}28,transparent)`, borderBottom:"1px solid rgba(240,200,80,0.08)", display:"flex", alignItems:"center", gap:"8px" }}>
              <span style={{ fontSize:"15px" }}>{card.badge}</span>
              <span style={{ fontSize:"10px", letterSpacing:"2.5px", color:card.accent, textTransform:"uppercase" }}>{card.label}</span>
            </div>

            {showImage && (
              <div style={{ padding:"18px 20px 12px", display:"flex", flexDirection:"column", justifyContent:"center", alignItems:"center", background:"rgba(255,255,255,0.02)", borderBottom:"1px solid rgba(240,200,80,0.06)", minHeight:"140px" }}>
                <img src={card.image} alt="technique" style={{ maxWidth:"100%", maxHeight:"200px", objectFit:"contain", borderRadius:"4px" }} />
                {card.caption && <div style={{ fontSize:"13px", color:"#e0c88a", marginTop:"10px", letterSpacing:"0.5px" }}>{card.caption}</div>}
              </div>
            )}
            {showText && (
              <div style={{ padding:"30px 20px", display:"flex", justifyContent:"center", alignItems:"center", background:"rgba(255,255,255,0.02)", borderBottom:"1px solid rgba(240,200,80,0.06)", minHeight:"100px" }}>
                <div style={{ fontSize:"clamp(20px,5vw,30px)", fontWeight:"700", color:"#f0d070", textAlign:"center", letterSpacing:"0.5px" }}>{card.prompt || card.answer}</div>
              </div>
            )}

            <div style={{ padding:"14px 20px 6px" }}>
              <div style={{ fontSize:"10px", color:"#705040", letterSpacing:"2px", textTransform:"uppercase" }}>{question}</div>
            </div>

            <div style={{ padding:"6px 16px 18px", display: card.type==="reverse" ? "grid" : "flex", gridTemplateColumns: card.type==="reverse" ? "1fr 1fr" : undefined, flexDirection: card.type==="reverse" ? undefined : "column", gap:"8px" }}>
              {card.options.map(opt => {
                const isCorrect = opt === card.answer;
                const isSelected = selected === opt;
                const revealed = selected !== null;
                let bg="rgba(255,255,255,0.025)", border="1px solid rgba(240,200,80,0.12)", color="#b09060", shadow="none", icon="›";
                if (revealed) {
                  if (isCorrect)       { bg="rgba(40,170,65,0.16)"; border="1px solid rgba(60,210,80,0.45)"; color="#70ee85"; shadow="0 0 14px rgba(40,200,60,0.2)"; icon="✓"; }
                  else if (isSelected) { bg="rgba(200,40,40,0.16)"; border="1px solid rgba(220,60,60,0.45)"; color="#ee7070"; shadow="0 0 14px rgba(200,40,40,0.2)"; icon="✗"; }
                  else { color="#504030"; }
                }
                if (card.type === "reverse") {
                  return (
                    <button key={opt} onClick={() => handleSelect(opt)}
                      style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:"6px", padding:"8px", borderRadius:"10px", background:bg, border, boxShadow:shadow, cursor:revealed?"default":"pointer", transition:"all 0.2s" }}>
                      <img src={IMAGES[name2key(opt)]} alt="option" style={{ maxWidth:"100%", maxHeight:"110px", objectFit:"contain", borderRadius:"4px", opacity:revealed && !isCorrect && !isSelected ? 0.4 : 1 }} />
                      {revealed && <span style={{ fontSize:"11px", color }}>{icon} {opt}</span>}
                    </button>
                  );
                }
                return (
                  <button key={opt} onClick={() => handleSelect(opt)}
                    style={{ display:"flex", alignItems:"center", gap:"10px", padding:"13px 15px", borderRadius:"10px", background:bg, border, boxShadow:shadow, color, fontFamily:"'Georgia',serif", fontSize:"15px", textAlign:"left", cursor:revealed?"default":"pointer", transition:"all 0.2s" }}>
                    <span style={{ fontSize:revealed?"14px":"11px", opacity:revealed?1:0.4, minWidth:"14px" }}>{icon}</span>
                    <span>{opt}</span>
                  </button>
                );
              })}
            </div>

            {selected && (
              <div style={{ padding:"0 16px 20px" }}>
                <button onClick={handleNext}
                  style={{ width:"100%", padding:"14px", borderRadius:"10px", border:"none", background:"linear-gradient(90deg,#f0c800,#f07820)", color:"#1a1200", fontFamily:"'Georgia',serif", fontSize:"15px", fontWeight:"700", letterSpacing:"1px", cursor:"pointer", boxShadow:"0 4px 18px rgba(240,150,30,0.3)" }}>
                  {index+1 >= cards.length ? "See Results" : "Next →"}
                </button>
              </div>
            )}
          </div>

          <div style={{ display:"flex", gap:"10px", marginTop:"18px" }}>
            <GhostBtn onClick={home}>⌂ Modes</GhostBtn>
            <GhostBtn onClick={restart}>↺ Restart</GhostBtn>
          </div>
        </>
      )}
    </div>
  );
}

function GhostBtn({ onClick, children }) {
  return (
    <button onClick={onClick}
      style={{ padding:"9px 16px", borderRadius:"8px", background:"transparent", border:"1px solid rgba(240,200,80,0.15)", color:"#706040", fontFamily:"'Georgia',serif", fontSize:"12px", letterSpacing:"1px", cursor:"pointer", transition:"all 0.2s" }}
      onMouseEnter={e => { e.currentTarget.style.color="#f0d070"; e.currentTarget.style.borderColor="rgba(240,200,80,0.45)"; }}
      onMouseLeave={e => { e.currentTarget.style.color="#706040"; e.currentTarget.style.borderColor="rgba(240,200,80,0.15)"; }}>
      {children}
    </button>
  );
}

function StartScreen({ belt, setBelt, onStart, wrap }) {
  const belts = ["All", ...BELT_ORDER];
  return (
    <div style={wrap}>
      <div style={{ textAlign:"center", marginBottom:"24px", paddingTop:"12px" }}>
        <div style={{ fontSize:"10px", letterSpacing:"4px", color:"#806840", textTransform:"uppercase", marginBottom:"4px" }}>Grading-Syllabus-Revised-v2503011</div>
        <h1 style={{ margin:0, fontSize:"clamp(20px,5vw,32px)", fontWeight:"700", color:"#f0d070", letterSpacing:"1px", textShadow:"0 0 24px rgba(240,200,80,0.3)" }}>🥋 Judo Technique Quiz</h1>
        <div style={{ fontSize:"11px", color:"#705030", marginTop:"6px", letterSpacing:"2px" }}>JUDO · ALL GRADES · CHOOSE A DRILL</div>
      </div>

      <div style={{ width:"100%", maxWidth:"600px", marginBottom:"20px" }}>
        <div style={{ fontSize:"10px", color:"#705040", letterSpacing:"2px", textTransform:"uppercase", marginBottom:"8px", textAlign:"center" }}>Belt level (cumulative)</div>
        <div style={{ display:"flex", flexWrap:"wrap", gap:"7px", justifyContent:"center" }}>
          {belts.map(b => (
            <button key={b} onClick={() => setBelt(b)}
              style={{ padding:"6px 12px", borderRadius:"20px", border: b===belt ? "1px solid rgba(240,200,80,0.6)" : "1px solid rgba(240,200,80,0.15)", background: b===belt ? "rgba(240,200,80,0.14)" : "transparent", color: b===belt ? "#f0d070" : "#806840", fontFamily:"'Georgia',serif", fontSize:"12px", letterSpacing:"0.3px", cursor:"pointer", transition:"all 0.2s" }}>
              {b}
            </button>
          ))}
        </div>
      </div>

      <div style={{ width:"100%", maxWidth:"580px", display:"flex", flexDirection:"column", gap:"10px" }}>
        {MODES.map(m => (
          <button key={m.id} onClick={() => onStart(m.id, belt)}
            style={{ display:"flex", alignItems:"center", gap:"14px", padding:"16px 18px", borderRadius:"12px", border:"1px solid rgba(240,200,80,0.16)", background:"linear-gradient(170deg,rgba(40,28,8,0.9),rgba(22,16,4,0.95))", color:"#e0c88a", fontFamily:"'Georgia',serif", textAlign:"left", cursor:"pointer", transition:"all 0.2s", boxShadow:"0 4px 18px rgba(0,0,0,0.4)" }}
            onMouseEnter={e => { e.currentTarget.style.borderColor="rgba(240,200,80,0.5)"; e.currentTarget.style.transform="translateY(-2px)"; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor="rgba(240,200,80,0.16)"; e.currentTarget.style.transform="translateY(0)"; }}>
            <span style={{ fontSize:"26px" }}>{m.icon}</span>
            <span style={{ display:"flex", flexDirection:"column" }}>
              <span style={{ fontSize:"16px", fontWeight:"700", color:"#f0d070", letterSpacing:"0.5px" }}>{m.title}</span>
              <span style={{ fontSize:"12px", color:"#907050", marginTop:"2px" }}>{m.desc}</span>
            </span>
          </button>
        ))}
      </div>
      <div style={{ fontSize:"10px", color:"#504030", marginTop:"22px", letterSpacing:"1px", textAlign:"center", maxWidth:"480px", lineHeight:"1.6" }}>
        Belt filter is cumulative — selecting a grade includes all earlier grades. Illustrated techniques (White-Yellow → Orange) appear in every mode; higher-grade throws, strangles and armlocks are covered by Classify, Terminology and the grading sim.
      </div>
    </div>
  );
}

function DoneScreen({ score, total, onRestart, onHome }) {
  const pct = total ? Math.round((score/total)*100) : 0;
  let emoji="🥋", msg="Keep training!";
  if(pct>=90){emoji="🏆";msg="Outstanding! Ready for grading!";}
  else if(pct>=75){emoji="⭐";msg="Great work! Almost there!";}
  else if(pct>=50){emoji="💪";msg="Good effort, keep practising!";}
  return (
    <div style={{ width:"100%", maxWidth:"580px", borderRadius:"14px", border:"1px solid rgba(240,200,80,0.2)", background:"linear-gradient(170deg,rgba(40,28,8,0.97),rgba(22,16,4,0.99))", boxShadow:"0 10px 50px rgba(0,0,0,0.7)", padding:"48px 28px", textAlign:"center" }}>
      <div style={{ fontSize:"52px", marginBottom:"14px" }}>{emoji}</div>
      <div style={{ fontSize:"34px", fontWeight:"700", color:"#f0d070", marginBottom:"6px" }}>{score} / {total}</div>
      <div style={{ fontSize:"18px", color:"#c09050", marginBottom:"6px" }}>{pct}%</div>
      <div style={{ fontSize:"14px", color:"#e0c88a", marginBottom:"36px", fontStyle:"italic" }}>{msg}</div>
      <div style={{ height:"5px", background:"#2a1e08", borderRadius:"3px", marginBottom:"36px" }}>
        <div style={{ height:"100%", borderRadius:"3px", background:pct>=75?"linear-gradient(90deg,#40c860,#80f890)":pct>=50?"linear-gradient(90deg,#f0c800,#f07820)":"linear-gradient(90deg,#c04030,#e06050)", width:`${pct}%`, transition:"width 0.8s ease" }} />
      </div>
      <div style={{ display:"flex", gap:"10px", justifyContent:"center" }}>
        <GhostBtn onClick={onHome}>⌂ Modes</GhostBtn>
        <button onClick={onRestart}
          style={{ padding:"12px 28px", borderRadius:"10px", border:"none", background:"linear-gradient(90deg,#f0c800,#f07820)", color:"#1a1200", fontFamily:"'Georgia',serif", fontSize:"14px", fontWeight:"700", letterSpacing:"1px", cursor:"pointer" }}>
          ↺ Try Again
        </button>
      </div>
    </div>
  );
}
